package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
)

const tasksFile = "tasks.json"

// Task represents a single todo item
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Exit functions for consistent error output
func exitWithError(err string, code int) {
	output := map[string]string{"error": err}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
	os.Exit(code)
}

func exitWithJSON(data interface{}) {
	jsonOutput, err := json.Marshal(data)
	if err != nil {
		exitWithError("failed to marshal JSON output", 1)
	}
	fmt.Println(string(jsonOutput))
	os.Exit(0)
}

func loadTasks() ([]Task, error) {
	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			return []Task{}, nil // No tasks file yet, return empty slice
		}
		return nil, fmt.Errorf("failed to read tasks file: %w", err)
	}

	var tasks []Task
	if len(data) == 0 {
		return []Task{}, nil // Empty file, return empty slice
	}
	err = json.Unmarshal(data, &tasks)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal tasks: %w", err)
	}
	return tasks, nil
}

func saveTasks(tasks []Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal tasks: %w", err)
	}
	err = ioutil.WriteFile(tasksFile, data, 0644)
	if err != nil {
		return fmt.Errorf("failed to write tasks file: %w", err)
	}
	return nil
}

func main() {
	if len(os.Args) < 2 {
		exitWithError("invalid arguments", 42)
	}

	switch os.Args[1] {
	case "add":
		addCmd := flag.NewFlagSet("add", flag.ExitOnError)
		description := addCmd.String("description", "", "Task description")
		addCmd.Parse(os.Args[2:])

		if *description == "" && len(addCmd.Args()) > 0 {
			*description = addCmd.Args()[0]
		}
		if *description == "" {
			exitWithError("invalid arguments", 42)
		}

		tasks, err := loadTasks()
		if err != nil {
			exitWithError(err.Error(), 1)
		}

		nextID := 1
		if len(tasks) > 0 {
			nextID = tasks[len(tasks)-1].ID + 1
		}

		newTask := Task{
			ID:          nextID,
			Description: *description,
			Done:        false,
		}
		tasks = append(tasks, newTask)

		err = saveTasks(tasks)
		if err != nil {
			exitWithError(err.Error(), 1)
		}

		exitWithJSON(map[string]interface{}{"id": newTask.ID, "status": "added"})

	case "list":
		listCmd := flag.NewFlagSet("list", flag.ExitOnError)
		listCmd.Parse(os.Args[2:])

		tasks, err := loadTasks()
		if err != nil {
			exitWithError(err.Error(), 1)
		}

		var pendingTasks []Task
		for _, task := range tasks {
			if !task.Done {
				pendingTasks = append(pendingTasks, task)
			}
		}
		exitWithJSON(pendingTasks)

	case "done":
		doneCmd := flag.NewFlagSet("done", flag.ExitOnError)
		doneCmd.Parse(os.Args[2:])

		if len(doneCmd.Args()) == 0 {
			exitWithError("invalid arguments", 42)
		}

		taskID, err := strconv.Atoi(doneCmd.Args()[0])
		if err != nil {
			exitWithError("invalid task ID", 42)
		}

		tasks, err := loadTasks()
		if err != nil {
			exitWithError(err.Error(), 1)
		}

		found := false
		for i, task := range tasks {
			if task.ID == taskID {
				tasks[i].Done = true
				found = true
				break
			}
		}

		if !found {
			exitWithError(fmt.Sprintf("task with ID %d not found", taskID), 42)
		}

		err = saveTasks(tasks)
		if err != nil {
			exitWithError(err.Error(), 1)
		}

		exitWithJSON(map[string]interface{}{"id": taskID, "status": "completed"})

	default:
		exitWithError("unknown command", 42)
	}
}

